package mrpapermoon.whisper.ui.utilsimport androidx.compose.material.CircularProgressIndicatorimport androidx.compose.material.LinearProgressIndicatorimport androidx.compose.runtime.Composableimport androidx.compose.runtime.Immutableimport androidx.compose.runtime.Stateimport androidx.compose.ui.Modifierimport mrpapermoon.whisper.ui.theme.WhisperColorsimport mrpapermoon.whisper.ui.widget.WhisperWaveBar@Composablefun ProgressBar(type: ProgressBarType, style: ProgressBarStyle, modifier: Modifier = Modifier) {	when (type) {		ProgressBarType.LINEAR -> LinearProgressBar(modifier, style)		ProgressBarType.CIRCLE -> CircleProgressBar(modifier, style)		ProgressBarType.WAVE -> WaveProgressBar(modifier, style)	}}@Composablefun LinearProgressBar(modifier: Modifier, style: ProgressBarStyle) {	when (style) {		is ProgressBarStyle.Fixed -> {			LinearProgressIndicator(modifier = modifier, color = WhisperColors.colorOnAccent, progress = style.progress.value)		}		ProgressBarStyle.Infinity -> {			LinearProgressIndicator(modifier = modifier, color = WhisperColors.colorOnAccent)		}	}}@Composablefun CircleProgressBar(modifier: Modifier, style: ProgressBarStyle) {	when (style) {		is ProgressBarStyle.Fixed -> {			CircularProgressIndicator(modifier = modifier, color = WhisperColors.colorOnAccent, progress = style.progress.value)		}		ProgressBarStyle.Infinity -> {			CircularProgressIndicator(modifier = modifier, color = WhisperColors.colorOnAccent)		}	}}@Composablefun WaveProgressBar(modifier: Modifier, style: ProgressBarStyle) {	when (style) {		is ProgressBarStyle.Fixed -> {			WhisperWaveBar(modifier = modifier, waveColor = WhisperColors.colorOnAccent, progress = style.progress.value)		}		ProgressBarStyle.Infinity -> {			WhisperWaveBar(modifier = modifier, waveColor = WhisperColors.colorOnAccent)		}	}}@Immutablesealed interface ProgressBarStyle {	data class Fixed(val progress: State<Float>) : ProgressBarStyle	object Infinity : ProgressBarStyle}enum class ProgressBarType {	LINEAR,	CIRCLE,	WAVE,	;}